            $this->aEstadoComInterna = null;
            $this->aPeriodo = null;
            $this->aDependencia = null;
            $this->aTipoComInterna = null;
            $this->aRegional = null;
            $this->aEstadoDigitalizacion = null;
            $this->aPrioridadCom = null;
            $this->aIdioma = null;
            $this->aTipoFirmaDigital = null;
