    {
        $this->modifiedColumns[] = ComInternaPeer::COMINTERNA_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(ComInternaPeer::COMINTERNA_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key (' . ComInternaPeer::COMINTERNA_ID . ')');
        }
        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(ComInternaPeer::COMINTERNA_ID);
        $pk = BasePeer::doInsert($criteria, $con);
        $this->setCominternaId($pk);  //[IMV] update autoincrement primary key
        $this->setNew(false);
    }

